// Explore3D runtime config — the single place the layered viewer reads its
// render contract from. The data is generated by
// scripts/skeleton/build-explore-body.mjs into public/models/explore-regions.json
// (from scripts/skeleton/body/registry.js), so the app never duplicates the
// build-side tables and the assets and their behaviour always agree.

import { getMappingBySlug } from './dhatuMapping.js';

export const EXPLORE_CONFIG_URL = '/models/explore-regions.json';

// Legacy fallback: the pre-layered body kept as the total-failure path.
export const LEGACY_BODY_URL = '/models/human-body.glb';

// Wrapper the whole body hangs from. The layered assets are authored in the
// same frame the skeleton already used (metres, Y up, anterior +Z, anatomical
// LEFT = +X, stature 1.72), so no re-fit is needed — these stay identity and
// are the only knobs for placement.
export const BODY_WRAPPER = {
  position: [0, 0, 0],
  rotation: [0, 0, 0],
  scale: 1,
};

// Per-layer surface response, keyed by layer. Tissue reads matte; wet internal
// structures (vessels, nerves, brain) keep a touch of sheen so they stay legible
// against muscle.
export const LAYER_PBR = {
  shell: { roughness: 0.58, metalness: 0.0 },
  meda: { roughness: 0.66, metalness: 0.0 },
  mamsa: { roughness: 0.7, metalness: 0.0 },
  rakta: { roughness: 0.38, metalness: 0.02 },
  rasa: { roughness: 0.45, metalness: 0.0 },
  majja: { roughness: 0.42, metalness: 0.0 },
  shukra: { roughness: 0.5, metalness: 0.0 },
  asthi: { roughness: 0.62, metalness: 0.05 },
};

// Regions that read differently from their layer's default surface response.
const REGION_PBR = {
  tendon: { roughness: 0.5, metalness: 0.0 },
  marrow: { roughness: 0.6, metalness: 0.0 },
  brain: { roughness: 0.46, metalness: 0.0 },
  heart: { roughness: 0.44, metalness: 0.02 },
  liver: { roughness: 0.52, metalness: 0.0 },
  spleen: { roughness: 0.52, metalness: 0.0 },
};

// Bones keep the four tones the skeleton viewer already used.
export const ASTHI_CATEGORY_TINT = {
  bone: '#EDE8DC',
  tooth: '#F5F0E1',
  cartilage: '#DFD2B5',
  disc: '#8C6B4E',
};

export function asthiCategory(name) {
  if (!name) return 'bone';
  if (name.startsWith('tooth_')) return 'tooth';
  if (name.startsWith('costal_cartilage_')) return 'cartilage';
  if (name.startsWith('disc_')) return 'disc';
  return 'bone';
}

/**
 * Layer a Dhatu wants in focus, straight from the shipped state table.
 */
export function targetLayerOf(cfg, slug) {
  const states = cfg?.dhatuLayerStates?.[slug];
  return states?.targetLayers?.[0] || null;
}

/**
 * The one state a mesh renders in for the current selection / hover.
 * 'target' = in focus, 'ghost' = occluding layer at <= 0.08 opacity,
 * 'context' = dimmed opaque surroundings, 'hover' = pointer is on it,
 * 'overview' = nothing selected.
 */
export function resolveExploreState(cfg, slug, region, hoveredRegion) {
  if (hoveredRegion && hoveredRegion === region.id) return 'hover';
  if (!slug) return 'overview';
  const states = cfg.dhatuLayerStates?.[slug];
  if (!states) return 'context';
  if (region.dhatus.includes(slug)) return 'target';
  if (states.targetLayers.includes(region.layer)) return 'context';
  if (states.ghostLayers.includes(region.layer) || states.ghostRegions.includes(region.id)) return 'ghost';
  return 'context';
}

/** Dhatu a region belongs to — the first tag, which is the site's primary one. */
export function primaryDhatuOf(region) {
  return region.dhatus.length ? region.dhatus[0] : null;
}

export function uiColorOf(slug, fallback = '#38bdf8') {
  const m = getMappingBySlug(slug);
  return m?.uiColor || fallback;
}

export function pbrOf(region) {
  return REGION_PBR[region.id] || LAYER_PBR[region.layer] || { roughness: 0.6, metalness: 0.0 };
}

let configPromise = null;

/** Cached fetch of the shipped config; rejects are cached too so the fallback
 *  path is reached once instead of on every retry. */
export function loadExploreConfig() {
  if (!configPromise) {
    configPromise = fetch(EXPLORE_CONFIG_URL).then((res) => {
      if (!res.ok) throw new Error(`explore-regions.json HTTP ${res.status}`);
      return res.json();
    }, (err) => {
      configPromise = null;
      throw err;
    });
  }
  return configPromise;
}

/** Index the region list once: the viewer looks regions up by id constantly. */
export function indexConfig(cfg) {
  const byId = new Map();
  for (const r of cfg.regions) byId.set(r.id, r);
  return { ...cfg, regionsById: byId };
}
